// The art budget, MEASURED by the compiler through the table. The declared
// number is what the generator counted; the equality assert is what makes a
// disagreement between the two a named build failure instead of a comment.
constexpr unsigned pb_sprite_atlas_bytes() {
  unsigned n = 0;
  for (unsigned i = 0; i < (unsigned)ER_SPRITE_SET_COUNT; ++i)
    n += spr_set_bytes(ER_SPRITE_SETS[i]);
  return n;
}
#define ER_SPRITE_DATA_BYTES          (pb_sprite_atlas_bytes())
#define ER_SPRITE_DATA_BYTES_DECLARED 9216u
#define ER_SPRITE_DATA_BYTES_MAX      10240u
static_assert(ER_SPRITE_DATA_BYTES == ER_SPRITE_DATA_BYTES_DECLARED,
              "generated atlas size disagrees with the generator");
static_assert(ER_SPRITE_DATA_BYTES <= ER_SPRITE_DATA_BYTES_MAX,
              "generated sprite art over its half of the flash budget");

// EVERY EYE BAND LIES INSIDE THE BODY IT BELONGS TO. pf_build_lids() blits
// the fill and lash strips at (x, y + y0) for (y1 - y0 + 1) rows with a plain
// drawXBM, so a band that runs past the sprite's own height writes rows that
// are not in the sprite - silently, on the device, with no diagnostic. The
// bands are derived, so this cannot fail from a typo; it CAN fail from a
// change to eye_band() or to the sprite dimensions, which is the whole reason
// it is a compile error and not a comment.
constexpr bool pb_sprite_eyes_fit() {
  for (unsigned i = 0; i < (unsigned)ER_SPRITE_SET_COUNT; ++i)
    for (unsigned f = 0; f < 2u; ++f) {
      const SpriteEyeBand& e = ER_SPRITE_EYES[i][f];
      if (e.y1 < e.y0) continue;            // 'does not blink'
      if (e.y1 >= ER_SPRITE_SETS[i].h) return false;
      if (e.x1 >= ER_SPRITE_SETS[i].w) return false;
      if (e.x1 < e.x0) return false;
    }
  return true;
}
static_assert(pb_sprite_eyes_fit(),
              "an eye band runs outside the sprite it indexes");

